def create_effective_prompt(task, context=None, examples=None, style=None):
    prompt = f"""Task: {task}
    """
    if context:
        prompt += f"Context: {context}\n"
    if examples:
        prompt += "Examples:\n"
        for example in examples:
            prompt += f"- {example}\n"
    if style:
        prompt += f"Style: {style}\n"
    return prompt
